import{_ as s,c as n,o as i,ag as t}from"./chunks/framework.bCALENAD.js";const h=JSON.parse('{"title":"Fragen & Antworten","description":"","frontmatter":{},"headers":[],"relativePath":"de/faq.md","filePath":"de/faq.md","lastUpdated":1720813884000}'),a={name:"de/faq.md"};function r(l,e,d,u,c,m){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="fragen-antworten" tabindex="-1">Fragen &amp; Antworten <a class="header-anchor" href="#fragen-antworten" aria-label="Permalink to &quot;Fragen &amp; Antworten&quot;">​</a></h1><p>Hier beantworten wir die Fragen, die Sie haben könnten.</p><details class="details custom-block"><summary>Wie installiere ich MySpeed?</summary><p>Je nach Betriebssystem sind diese Anweisungen unterschiedlich. Hier finden Sie die Anweisungen für <a href="./setup/windows">Windows</a> und <a href="./setup/linux">Linux</a>. Es wird jedoch dringend empfohlen, MySpeed unter Linux zu installieren.</p></details><details class="details custom-block"><summary>Was sind die Anforderungen?</summary><p>Es hängt davon ab, welche Art von Bandbreite Sie haben. Für Linux könnte es so aussehen: Wenn Sie maximal 100 Mbps haben, reicht ein Raspberry Pi 1 oder ein anderer alter Computer aus. Bei einer Gbit-Leitung sind ein Raspberry Pi 4 oder ein PC mit 1Gbit LAN-Unterstützung wichtig.</p></details><details class="details custom-block"><summary>Kann ich MySpeed trotz VPN verwenden?</summary><p>Solange Sie Ihren VPN-Dienst nicht auf dem gleichen System verwenden, auf dem MySpeed läuft, gibt es kein Problem. Andernfalls könnten Ihre VPN-Einstellungen die Ergebnisse verzerren oder diese nicht realistisch widerspiegeln.</p></details><details class="details custom-block"><summary>Dient diese Information als offizieller Nachweis für meinen ISP?</summary><p>Nein. Die Geschwindigkeitstests müssen vom Geschwindigkeitstestdienst Ihres Anbieters durchgeführt werden. In diesem Fall dient MySpeed nur zu Informationszwecken und bietet keine rechtliche Garantie.</p></details><details class="details custom-block"><summary>Was kann die Geschwindigkeitstests beeinflussen?</summary><p>Es gibt viele Faktoren, die die Geschwindigkeitstests beeinflussen können. Zum Beispiel können Hintergrunddienste die Ergebnisse beeinflussen. Es ist am besten, sie während der jeweiligen Testzeiten auszuschalten, da sonst Ihre Ergebnisse manipuliert werden könnten.</p></details><details class="details custom-block"><summary>Was passiert mit den alten Testergebnissen?</summary><p>Die alten Testergebnisse werden automatisch gelöscht, sobald sie älter als 30 Tage sind.</p></details><details class="details custom-block"><summary>Muss MySpeed dauerhaft laufen?</summary><p>Wir empfehlen es, um bessere Ergebnisse zu erzielen. Wenn es Sie beim Streamen von Filmen usw. stört, können Sie es über die Web-Schnittstelle für eine bestimmte Zeit pausieren oder manuell anhalten. Für den 24/7-Betrieb empfehlen wir ein System, das nicht viel Strom verbraucht. In diesem Fall empfehlen wir einen Raspberry Pi. Wenn Sie bereits einen Server haben, der ständig läuft, können Sie es auch dort parallel laufen lassen.</p></details><details class="details custom-block"><summary>Wie kann ich zwischen manuellen und automatischen Geschwindigkeitstests unterscheiden?</summary><p>Klicken Sie auf das Uhrsymbol des jeweiligen Tests. Dort finden Sie alle Informationen zum Geschwindigkeitstest.</p></details><details class="details custom-block"><summary>Zeigt die &quot;Empfehlungen&quot;-Funktion meine tatsächliche Bandbreite an?</summary><p>Nein, dies ist ein berechneter Wert aus Ihren letzten 10 Geschwindigkeitstests. Die verfügbare Bandbreite finden Sie in Ihrem Vertragsangebot.</p></details><details class="details custom-block"><summary>Kann der Entwickler meine Testergebnisse sehen?</summary><p>Nein, die Testergebnisse sind nur lokal auf dem Server sichtbar.</p></details><details class="details custom-block"><summary>Warum sollte ich Frequenzen konfigurieren?</summary><p>Es hängt stark von Ihrem Internet ab. Wenn Sie z.B. eine sehr schlechte Internetverbindung haben, sollten Sie die Frequenz eher verringern. Wenn Ihr Internet jedoch recht schnell ist, können Sie sie erhöhen. Auf dieser Grundlage werden mehr oder weniger Tests je nach Situation durchgeführt.</p><div class="warning custom-block"><p class="custom-block-title">Achtung</p><p>Es ist sehr wahrscheinlich, dass Hintergrunddienste Ihre Geschwindigkeiten beeinflussen. Es ist am besten, sie während der jeweiligen Testzeiten auszuschalten, da sonst Ihre Ergebnisse manipuliert werden könnten.</p></div></details><details class="details custom-block"><summary>Wie setze ich mein Passwort zurück?</summary><p>Sie haben Ihr MySpeed-Passwort vergessen? Kein Problem. Um es zurückzusetzen, navigieren Sie zum Installationsort (<code>cd /opt/myspeed</code>) und führen Sie den folgenden Befehl aus:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;const {Sequelize} = require(&#39;sequelize&#39;);const db = new Sequelize({dialect: &#39;sqlite&#39;, storage: &#39;data/storage.db&#39;});db.query(&#39;UPDATE config SET value=? WHERE key=?&#39;, {replacements: [&#39;none&#39;, &#39;password&#39;]})&quot;</span></span></code></pre></div><p>Dann können Sie die Seite erneut aufrufen und Ihr Passwort manuell setzen 😃</p></details>',14)])])}const p=s(a,[["render",r]]);export{h as __pageData,p as default};
